// Project-wide declarations to allow imports of JS/JSX pages referenced by generated types.
declare module '*./src/app/./page.jsx' {
  const v: any;
  export default v;
}

declare module '*../page.js' {
  const v: any;
  export default v;
}

declare module '@/src/app/page.jsx' {
  const v: any;
  export default v;
}
